def resolve(path, cwd, links):
    # Validate inputs
    if not cwd or cwd[0] != '/':
        return None

    # Normalize cwd - remove trailing slash unless it's root
    if cwd != '/' and cwd.endswith('/'):
        return None

    # Start with cwd if path is relative
    if not path or path[0] != '/':
        current = cwd
    else:
        current = '/'

    # Split path into components
    if path and path[0] == '/':
        components = path[1:].split('/')
    else:
        # Relative path - append to cwd
        if path:
            components = path.split('/')
        else:
            components = []

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if not comp or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current == '/':
                continue
            # Move to parent
            last_slash = current.rfind('/')
            if last_slash == 0:
                current = '/'
            else:
                current = current[:last_slash]
            continue

        # Append the component
        if current == '/':
            current = '/' + comp
        else:
            current = current + '/' + comp

        # Check if current path is a symlink
        if current in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[current]

            # Parse target into components
            if target[0] == '/':
                # Absolute target - start from root
                current = '/'
                target_components = target[1:].split('/')
            else:
                # Relative target - resolve from the directory containing the link
                last_slash = current.rfind('/')
                if last_slash == 0:
                    current = '/'
                else:
                    current = current[:last_slash]
                target_components = target.split('/')

            # Insert remaining components and target components
            remaining = components[i:]
            components = target_components + remaining
            i = 0

    # Remove trailing slash unless it's root
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

